<script setup lang="ts">
import { PropType, ref, watch } from "vue";
// Insert 仅作类型使用；NormalToolbar 需要用运行时代码，这里保留对 md-editor-v3 的静态导入
import type { Insert } from "md-editor-v3";
import { NormalToolbar } from "md-editor-v3";
import { LoadingIcon, RocketIcon } from "tdesign-icons-vue-next";
import { AIEnhancementInterruptedError, AIEnhancementRequestError, PostProblemAIEnhancement } from "@/apis/problem.ts";
import { GetText } from "@/text/library.ts";

const props = defineProps({
  modelValue: {
    type: String as PropType<string>,
    default: "",
  },
  insert: {
    type: Function as PropType<Insert>,
    default: () => {
      //
    },
  },
  // AI 服务是否就绪：为 false 时不渲染入口按钮（与设计文档 §8 的「ai_enabled=false 时隐藏按钮」一致）
  aiEnabled: {
    type: Boolean,
    default: true,
  },
});

const emit = defineEmits(["update:modelValue"]);

const drawerVisible = ref(false);
const previewContent = ref("");
const thinkingContent = ref("");
const isThinking = ref(false);
const abortController = ref<AbortController | null>(null);
const isLoading = ref(false);
const isGenerating = ref(false);
const errorMessage = ref("");
const inactivitySeconds = ref(0);
const thinkingCollapsed = ref(false);
const activeTab = ref("preview");
const copySuccess = ref(false);

// 生成是否正常结束（收到 done 事件）。
// 「替换」必须以它为准：流被掐断时函数同样会返回，若不看该标志会把截断内容当成品写回编辑器
const isCompleted = ref(false);
// 流被中断（已产出部分内容但未正常结束）
const isInterrupted = ref(false);
// 中断后用户选择「查看已生成内容」：跳过错误占位、直接渲染部分结果
const showPartialOnInterrupt = ref(false);

/** 统一复位一次生成的所有状态 */
const resetRunState = () => {
  previewContent.value = "";
  thinkingContent.value = "";
  isThinking.value = false;
  errorMessage.value = "";
  isCompleted.value = false;
  isInterrupted.value = false;
  showPartialOnInterrupt.value = false;
};

// 不活动计时：与后端对齐，收到任何 AI 事件时重置
let inactivityTimer: ReturnType<typeof setInterval> | null = null;
const INACTIVITY_TIMEOUT = 35;

const startInactivityTimer = () => {
  inactivitySeconds.value = 0;
  inactivityTimer = setInterval(() => {
    inactivitySeconds.value++;
    if (inactivitySeconds.value >= INACTIVITY_TIMEOUT) {
      handleInactivityTimeout();
    }
  }, 1000);
};

const resetInactivityTimer = () => {
  inactivitySeconds.value = 0;
};

const stopInactivityTimer = () => {
  if (inactivityTimer) {
    clearInterval(inactivityTimer);
    inactivityTimer = null;
  }
};

const handleInactivityTimeout = () => {
  stopInactivityTimer();
  if (abortController.value) {
    abortController.value.abort();
    abortController.value = null;
  }
  isLoading.value = false;
  isThinking.value = false;
  isGenerating.value = false;
  errorMessage.value = "AI 服务响应超时，请稍后重试";
};

/** 错误码优先查项目文案表，取不到则回退到后端下发的原文 */
const resolveErrorMessage = (message: string, code?: number) => {
  if (code) {
    const [found, text] = GetText(code);
    if (found) {
      return text;
    }
  }
  return message;
};

const handler = async () => {
  if (abortController.value) {
    abortController.value.abort();
    abortController.value = null;
  }

  resetRunState();
  isLoading.value = true;
  isGenerating.value = true;
  drawerVisible.value = true;
  startInactivityTimer();

  abortController.value = new AbortController();

  try {
    await PostProblemAIEnhancement(
      props.modelValue,
      {
        onThinking: (chunk) => {
          isLoading.value = false;
          isThinking.value = true;
          resetInactivityTimer();
          thinkingContent.value += chunk;
        },
        onChunk: (chunk) => {
          isLoading.value = false;
          isThinking.value = false;
          resetInactivityTimer();
          previewContent.value += chunk;
        },
        onHeartbeat: () => {
          resetInactivityTimer();
        },
        onError: (message, code) => {
          isLoading.value = false;
          isThinking.value = false;
          isGenerating.value = false;
          stopInactivityTimer();
          errorMessage.value = resolveErrorMessage(message, code);
        },
        onInterrupted: (message) => {
          isLoading.value = false;
          isThinking.value = false;
          isGenerating.value = false;
          stopInactivityTimer();
          isInterrupted.value = true;
          errorMessage.value = message || "生成被中断，内容可能不完整，请重试";
        },
        onDone: () => {
          isThinking.value = false;
          isGenerating.value = false;
          isCompleted.value = true;
          stopInactivityTimer();
        },
      },
      abortController.value.signal
    );
  } catch (e) {
    isLoading.value = false;
    isThinking.value = false;
    isGenerating.value = false;
    stopInactivityTimer();
    // 中止请求不算失败，其余错误统一提示（e 为 unknown，故先收窄）
    const errorName = e instanceof Error ? e.name : "";
    if (errorName !== "AbortError") {
      if (e instanceof AIEnhancementRequestError) {
        errorMessage.value = resolveErrorMessage(e.message, e.code);
      } else if (e instanceof AIEnhancementInterruptedError) {
        isInterrupted.value = true;
        errorMessage.value = e.message;
      } else {
        errorMessage.value = "请求失败，请稍后重试";
      }
    }
  }

  isGenerating.value = false;
  stopInactivityTimer();
};

const handleConfirm = () => {
  emit("update:modelValue", "");
  props.insert((_selectedText) => {
    return {
      targetValue: previewContent.value,
      select: false,
      deviationStart: 0,
      deviationEnd: 0,
    };
  });
  drawerVisible.value = false;
  previewContent.value = "";
  thinkingContent.value = "";
};

const handleStop = () => {
  if (abortController.value) {
    abortController.value.abort();
    abortController.value = null;
    isGenerating.value = false;
    isLoading.value = false;
    isThinking.value = false;
    stopInactivityTimer();
  }
};

const handleCancel = () => {
  drawerVisible.value = false;
  previewContent.value = "";
  thinkingContent.value = "";
};

const handleRetry = () => {
  errorMessage.value = "";
  handler();
};

const handleCopyRaw = async () => {
  try {
    await navigator.clipboard.writeText(previewContent.value);
    copySuccess.value = true;
    setTimeout(() => {
      copySuccess.value = false;
    }, 2000);
  } catch {
    // 降级方案：使用 textarea 复制
    const textarea = document.createElement("textarea");
    textarea.value = previewContent.value;
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand("copy");
    document.body.removeChild(textarea);
    copySuccess.value = true;
    setTimeout(() => {
      copySuccess.value = false;
    }, 2000);
  }
};

watch(drawerVisible, (newVal) => {
  if (!newVal && abortController.value) {
    abortController.value.abort();
    abortController.value = null;
  }
  if (!newVal) {
    stopInactivityTimer();
  }
});
</script>

<template>
  <NormalToolbar v-if="aiEnabled" title="AI美化" @on-click="handler">
    <RocketIcon />
  </NormalToolbar>

  <t-drawer
    v-model:visible="drawerVisible"
    header="AI美化预览"
    size="large"
    :footer="true"
    :show-overlay="false"
    :size-draggable="true"
    :close-on-overlay-click="true"
  >
    <div class="preview-container">
      <div v-if="errorMessage && !showPartialOnInterrupt" class="error-container">
        <t-icon
          :name="isInterrupted ? 'error-circle' : 'close-circle'"
          size="32px"
          :style="{ color: isInterrupted ? 'var(--td-warning-color)' : 'var(--td-error-color)' }"
        />
        <p class="error-message">{{ errorMessage }}</p>
        <t-space>
          <t-button theme="primary" variant="text" @click="handleRetry">重试</t-button>
          <!-- 中断时已产出的内容可能仍有参考价值，允许用户查看与复制（但不提供直接替换） -->
          <t-button v-if="isInterrupted && previewContent" theme="default" variant="text" @click="showPartialOnInterrupt = true">
            查看已生成内容（{{ previewContent.length }} 字）
          </t-button>
        </t-space>
      </div>
      <div v-else-if="isLoading" class="loading-container">
        <t-loading text="AI 正在连接中..." size="medium" />
        <p v-if="inactivitySeconds > 5" class="waiting-hint">已等待 {{ inactivitySeconds }} 秒</p>
      </div>
      <div v-else>
        <!-- 中断态告警：显式告知内容不完整，且不提供「替换」 -->
        <t-alert
          v-if="isInterrupted"
          theme="warning"
          :message="errorMessage"
          description="内容可能不完整，建议重试后再替换正文。可先查看或复制下方已生成的部分。"
          class="interrupted-alert"
        />
        <!-- 思考过程展示 -->
        <div v-if="thinkingContent" class="thinking-section">
          <div class="thinking-header" @click="thinkingCollapsed = !thinkingCollapsed">
            <t-icon name="chat" />
            <span>思考过程</span>
            <t-icon :name="thinkingCollapsed ? 'chevron-down' : 'chevron-up'" />
          </div>
          <div v-show="!thinkingCollapsed" class="thinking-body">
            <pre class="thinking-text">{{ thinkingContent }}</pre>
            <div v-if="isThinking" class="thinking-indicator">
              <t-loading size="small" />
              <span>思考中...</span>
            </div>
          </div>
        </div>
        <!-- 结果展示：有正式输出时显示 Tabs 切换，否则直接显示预览 -->
        <template v-if="previewContent">
          <t-tabs v-model="activeTab" class="result-tabs">
            <t-tab-panel value="preview" label="预览">
              <md-preview :model-value="previewContent" preview-theme="cyanosis" />
            </t-tab-panel>
            <t-tab-panel value="raw" label="原始文本">
              <div class="raw-text-container">
                <t-button size="small" variant="text" :theme="copySuccess ? 'success' : 'primary'" class="copy-btn" @click="handleCopyRaw">
                  {{ copySuccess ? "已复制" : "复制" }}
                </t-button>
                <pre class="raw-text">{{ previewContent }}</pre>
              </div>
            </t-tab-panel>
          </t-tabs>
        </template>
        <template v-else>
          <md-preview :model-value="previewContent" preview-theme="cyanosis" />
        </template>
        <div v-if="isGenerating" class="generating-hint">
          <t-loading size="small" />
          <span>AI 正在生成中...</span>
        </div>
      </div>
    </div>
    <template #footer>
      <t-space>
        <t-button theme="default" @click="handleCancel">取消</t-button>
        <t-button v-if="isGenerating" theme="danger" @click="handleStop">
          <template #icon>
            <LoadingIcon />
          </template>
          停止
        </t-button>
        <!-- 禁用条件以 isCompleted 为准：流被掐断时函数同样会返回，
             若只看 errorMessage 会把截断内容当成品写回编辑器 -->
        <t-button v-else theme="primary" :disabled="!isCompleted || !previewContent" @click="handleConfirm">替换 </t-button>
      </t-space>
    </template>
  </t-drawer>
</template>

