<script setup lang="ts">
import { ref, computed, onMounted } from "vue";
import { useRoute } from "vue-router";
import router from "@/router";
import { ChevronDownIcon } from "tdesign-icons-vue-next";
import { HandleR2ImageUpload } from "@/util/md-editor-v3.ts";
import AIEnhancement from "@/components/markdown/AIEnhancement.vue";
import { useWebStyleStore } from "@/stores/webStyle.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetProblem,
  GetProblemJudge,
  GetProblemTagList,
  GetProblemTagHistory,
  ParseProblem,
  GetProblemImageToken,
  PostProblemCreate,
  PostProblemEdit,
  PostProblemTagReset,
} from "@/apis/problem.ts";
import type { ProblemTag, ProblemTagChange, ProblemView } from "@/types/problem.ts";
import { SpaceType, GetSpaceTypeDescription } from "@/apis/judge.ts";
import type { CheckboxGroupChangeContext, CheckboxGroupValue, TagInputChangeContext, TagInputValue } from "tdesign-vue-next";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { PostEnrichTagSuggest } from "@/apis/problem-enrichment";
import { ShowTextTipsError } from "@/util/tips";

const route = useRoute();
const { globalProperties } = useCurrentInstance();

const webStyleStore = useWebStyleStore();
const { isMobile } = useBreakpoint();

// 出题环节按标签找相似题：零成本复用题目列表的标签筛选（spec §2.1：相似题生成挪到出题环节）。
// 列表接口的标签条件是「命中任一」，这里取当前填写的第一个标签作为主算法标签检索。
const handleFindSimilar = () => {
  const firstTag = problemEditForm.value.tags.find((t) => t.trim() !== "");
  if (!firstTag) {
    ShowTextTipsSuccess(globalProperties, "请先填写至少一个标签");
    return;
  }
  router.push({ name: "problem-list", query: { tag: firstTag.trim(), page: "1", page_size: "50" } });
};

let problemId = 0;
const problemKey = ref("");
const problemLoading = ref(false);
const isSaving = ref(false);
const disabledEdit = ref(false);
// AI 服务是否就绪：由后端 ai_enabled 决定（AI 未配置时隐藏 AI 入口，与设计文档一致）
const aiEnabled = ref(false);
// md-editor-v3 实例：当前只通过 v-model 交互，无需在脚本里读取组件实例
// （原来声明了 editorRef 并在模板上挂 ref，但脚本从未使用，且模板里也没有 `editorRef.` 之类的读取）

const fullToolbars = [
  "bold",
  "underline",
  "italic",
  "-",
  "title",
  "strikeThrough",
  "sub",
  "sup",
  "quote",
  "unorderedList",
  "orderedList",
  "task",
  "-",
  "codeRow",
  "code",
  "link",
  "image",
  "table",
  "mermaid",
  "katex",
  0,
  "-",
  "revoke",
  "next",
  "save",
  "=",
  "pageFullscreen",
  "fullscreen",
  "preview",
  "previewOnly",
  "htmlPreview",
  "catalog",
  "github",
];

const mobileToolbars = [
  "bold",
  "italic",
  "-",
  "title",
  "quote",
  "unorderedList",
  "orderedList",
  "-",
  "codeRow",
  "code",
  "image",
  "table",
  "=",
  "pageFullscreen",
  "preview",
];

const toolbars = computed(() => (isMobile.value ? mobileToolbars : fullToolbars));

const problemData = ref<ProblemView | null>(null);

const problemEditForm = ref({
  title: "",
  timeLimit: 0,
  memoryLimit: 0,
  source: "",
  private: true,
  tags: [] as string[],
  description: "",
  spaceType: SpaceType.Normal as number,
});

const spaceTypeOptions = [
  { label: "忽略末尾换行", value: SpaceType.Normal },
  { label: "严格对比", value: SpaceType.Strict },
  { label: "忽略行末空格", value: SpaceType.IgnoreTrailing },
];

const spaceTypeDescription = computed(() => GetSpaceTypeDescription(problemEditForm.value.spaceType));

/**
 * 题目标签选项
 *
 * value 通常是标签 id（数字）；但用户手动输入的新标签没有 id，
 * 此时 label/value 都取用户输入的文本，因此 value 允许字符串
 */
interface ProblemTagOption {
  label: string;
  value: string | number;
  /** 关联来源：ai = AI 审阅自动补的，human = 人工挂的（未保存的新标签为空） */
  source?: string;
  /** 是否为服务端已保存的标签：用于判断「这次编辑删掉了什么」 */
  saved?: boolean;
}

const problemTags = ref<ProblemTagOption[]>([]);
const problemTagOptions = ref<ProblemTagOption[]>([]);

// ── 人工与 AI 的边界（用户可见规则只有一条：你动过的，AI 不会改） ──
// 本次编辑中被移除的、原本已保存的标签：保存后它们会被登记为「AI 禁加」，
// 所以界面上要明确告诉用户「删了就不会被 AI 加回来」，并给一个撤销出口。
const removedSavedTags = ref<string[]>([]);
// 服务端原始的标签集合，供撤销删除时还原
const originalTags = ref<ProblemTagOption[]>([]);
// 标签改动记录（AI 与人工的动作都在这），默认收起
const tagHistory = ref<ProblemTagChange[]>([]);
const tagHistoryLoading = ref(false);
const showTagHistory = ref(false);
const tagResetLoading = ref(false);

// 按关联来源分组：用户一眼要能看出哪几个是 AI 给的
const humanTags = computed(() => problemTags.value.filter((t) => t.source !== "ai"));
const aiTags = computed(() => problemTags.value.filter((t) => t.source === "ai"));
const humanTagNames = computed(() => humanTags.value.map((t) => t.label).join("、"));
const aiTagNames = computed(() => aiTags.value.map((t) => t.label).join("、"));

const problemTagsCheckbox = computed(() => {
  const arr = [];
  const list = problemTags.value;
  // 此处不使用 forEach，减少函数迭代
  for (let i = 0, len = list.length; i < len; i++) {
    if (list[i].value) {
      arr.push(list[i].value);
    }
  }
  return arr;
});

// 记录本次编辑中被移除的、服务端已保存的标签。
// 未保存的新标签不用记：它本来就没进过库，也无所谓「被 AI 加回来」。
const recordRemoved = (list: (ProblemTagOption | undefined)[]) => {
  for (const tag of list) {
    if (!tag || !tag.saved) {
      continue;
    }
    if (!removedSavedTags.value.includes(tag.label)) {
      removedSavedTags.value.push(tag.label);
    }
  }
};

// 撤销一次删除：把标签放回去，并取消「AI 禁加」的提示
const handleRevokeRemoved = (label: string) => {
  removedSavedTags.value = removedSavedTags.value.filter((name) => name !== label);
  if (problemTags.value.some((t) => t.label === label)) {
    return;
  }
  const origin = originalTags.value.find((t) => t.label === label);
  problemTags.value.push(origin ?? { label, value: label });
};

const onTagChange = (_value: TagInputValue, context: TagInputChangeContext) => {
  const { trigger, index, item } = context;
  if (trigger === "clear") {
    recordRemoved(problemTags.value);
    problemTags.value = [];
  }
  if (["tag-remove", "backspace"].includes(trigger) && index !== undefined) {
    recordRemoved([problemTags.value[index]]);
    problemTags.value.splice(index, 1);
  }
  // 回车新增：tdesign 在 enter 场景下一定会带上输入框文本（字符串）
  if (trigger === "enter" && typeof item === "string") {
    for (let i = 0; i < problemTagOptions.value.length; i++) {
      const tag = problemTagOptions.value[i];
      if (tag.label === item) {
        for (let j = 0; j < problemTags.value.length; j++) {
          if (problemTags.value[j].label === tag.label) {
            return;
          }
        }
        problemTags.value.push(tag);
        return;
      }
    }
    const current = { label: item, value: item };
    problemTags.value.push(current);
    problemTagOptions.value = problemTagOptions.value.concat(current);
  }
};

const onTagCheckedChange = (_value: CheckboxGroupValue, { current, type }: CheckboxGroupChangeContext) => {
  // current 不存在，则表示操作全选
  if (!current) {
    problemTags.value = type === "check" ? problemTagOptions.value.slice(1) : [];
    return;
  }
  // 普通操作
  if (type === "check") {
    const option = problemTagOptions.value.find((t) => t.value === current);
    if (!option) {
      return;
    }
    problemTags.value.push(option);
  } else {
    problemTags.value = problemTags.value.filter((v) => v.value !== current);
  }
};

// AI 生成标签：优先用 AI 产出候选，出题人可手动增删后再保存
const aiTagLoading = ref(false);
const handleAiSuggestTags = async () => {
  aiTagLoading.value = true;
  try {
    const res = await PostEnrichTagSuggest(
      problemEditForm.value.title,
      problemEditForm.value.description
    );
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    const data = res.data;
    const candidates = [...(data?.canonical ?? []), ...(data?.raw ?? [])];
    if (!candidates.length) {
      ShowTextTipsError(globalProperties, "AI 未产出标签，请检查题面或手动填写");
      return;
    }
    let added = 0;
    for (const name of candidates) {
      if (problemTags.value.some((t) => t.label === name)) {
        continue;
      }
      // 词表内标签优先匹配选项（保留 id）；新词以文本形式加入
      const option = problemTagOptions.value.find((t) => t.label === name);
      problemTags.value.push(option ?? { label: name, value: name });
      added++;
    }
    if (!added) {
      ShowTextTipsError(globalProperties, "AI 候选标签已全部存在");
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "AI 标签生成失败");
  } finally {
    aiTagLoading.value = false;
  }
};

const handleClickView = () => {
  router.push({
    name: "problem-detail",
    params: {
      problemKey: problemKey.value,
    },
  });
};

const handleClickJudge = () => {
  router.push({
    name: "manage-problem-judge",
    params: {
      problemKey: problemKey.value,
    },
  });
};

const handleClickAi = () => {
  router.push({
    name: "manage-problem-judge-ai",
    params: {
      problemKey: problemKey.value,
    },
  });
};

const onUploadImg = async (files: File[], callback: (urls: { url: string; alt: string; title: string }[]) => void) => {
  disabledEdit.value = true;
  await HandleR2ImageUpload(files, callback, globalProperties, () => {
    return GetProblemImageToken(problemId);
  });
  disabledEdit.value = false;
};

const handleClickCreate = async () => {
  isSaving.value = true;

  problemEditForm.value.tags = [];
  for (let i = 0; i < problemTags.value.length; i++) {
    const tag = problemTags.value[i];
    if (tag && tag.label) {
      problemEditForm.value.tags.push(tag.label);
    }
  }

  try {
    const res = await PostProblemCreate(
      problemEditForm.value.title,
      problemEditForm.value.timeLimit,
      problemEditForm.value.memoryLimit,
      problemEditForm.value.source,
      problemEditForm.value.private,
      problemEditForm.value.tags,
      problemEditForm.value.description,
      problemEditForm.value.spaceType
    );

    isSaving.value = true;

    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }

    if (res.data != undefined) {
      await router.push({
        name: "problem-detail",
        params: { problemKey: res.data },
      });
    }

    ShowTextTipsSuccess(globalProperties, "创建成功");
  } finally {
    isSaving.value = false;
  }
};

const handleClickSave = async () => {
  isSaving.value = true;

  problemEditForm.value.tags = [];
  for (let i = 0; i < problemTags.value.length; i++) {
    const tag = problemTags.value[i];
    if (tag && tag.label) {
      problemEditForm.value.tags.push(tag.label);
    }
  }

  try {
    const res = await PostProblemEdit(
      problemId,
      problemEditForm.value.title,
      problemEditForm.value.timeLimit,
      problemEditForm.value.memoryLimit,
      problemEditForm.value.source,
      problemEditForm.value.private,
      problemEditForm.value.tags,
      problemEditForm.value.description,
      problemEditForm.value.spaceType
    );

    isSaving.value = true;

    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }

    if (problemData.value) {
      if (res.data.modify_time != undefined) {
        problemData.value.modifyTime = new Date(res.data.modify_time).toLocaleString();
      }
    }
    if (res.data.description != undefined) {
      problemEditForm.value.description = res.data.description;
    }

    // 保存成功：这次的增删已经落到服务端（被删的标签已登记为「AI 禁加」），
    // 提示行与原始集合必须同步刷新，否则界面还在提示一件已经生效的事
    removedSavedTags.value = [];
    problemTags.value.forEach((tag) => {
      tag.saved = true;
    });
    originalTags.value = problemTags.value.map((t) => ({ ...t }));
    loadTagHistory();

    ShowTextTipsSuccess(globalProperties, "保存成功");
  } finally {
    isSaving.value = false;
  }
};

const onEditSave = async () => {
  if (problemId) {
    await handleClickSave();
  } else {
    await handleClickCreate();
  }
};

const loadDescriptionEditor = (description: string) => {
  problemEditForm.value.description = description;
  problemLoading.value = false;
};

const loadProblem = async () => {
  const res = await GetProblem(problemKey.value, undefined, undefined);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    console.error("problem get failed", res.code);
    await router.push({ name: "problem" });
    return;
  }

  const problem = res.data.problem;

  problemId = problem.id;

  problemData.value = ParseProblem(problem, {});

  problemEditForm.value.title = problem.title;
  problemEditForm.value.timeLimit = problem.time_limit;
  problemEditForm.value.memoryLimit = problem.memory_limit;
  problemEditForm.value.source = problem.source;
  problemEditForm.value.private = problem.private;
  problemEditForm.value.spaceType = problem.space_type ?? SpaceType.Normal;

  problemEditForm.value.tags = [];
  problemTags.value = [];
  removedSavedTags.value = [];
  if (res.data.tags) {
    for (let i = 0; i < res.data.tags.length; i++) {
      const tag = res.data.tags[i];
      if (tag && tag.name) {
        problemEditForm.value.tags.push(tag.name);
        problemTags.value.push({
          label: tag.name,
          value: tag.id,
          // 关联来源（ai/human）：编辑页据此告诉用户哪几个是 AI 补的
          source: tag.relation_source,
          saved: true,
        });
      }
    }
  }
  // 原始集合留一份：撤销删除时用它把标签（含来源）原样还原
  originalTags.value = problemTags.value.map((t) => ({ ...t }));
  loadTagHistory();

  webStyleStore.setTitle(problem.title + " - " + webStyleStore.getTitle);

  const problemDescription = problem.description as string;

  loadDescriptionEditor(problemDescription);

  // AI 可用性：失败不阻塞题目编辑，保持隐藏（aiEnabled 初始为 false）
  loadAiEnabled();
};

// 标签改动记录（AI 与人工的动作都在这里）。
// 没有它，用户永远不知道 AI 在背后改了什么，「AI 会不会偷偷改我的东西」就无法回答。
const loadTagHistory = async () => {
  if (!problemId) {
    tagHistory.value = [];
    return;
  }
  tagHistoryLoading.value = true;
  try {
    const res = await GetProblemTagHistory(problemId);
    if (res.code === 0) {
      tagHistory.value = res.data?.list ?? [];
    }
  } catch (err) {
    console.error(err);
  } finally {
    tagHistoryLoading.value = false;
  }
};

// 「让 AI 重新决定这道题的标签」：解禁被人工移除的标签，并强制重跑 AI 审阅。
// 不会立刻改变现状——要等下次审阅跑完才生效，所以提示文案必须写清这一点，
// 否则用户会以为按钮没反应而重复点击。
const handleResetTagsToAi = async () => {
  if (!problemId) {
    ShowTextTipsError(globalProperties, "题目尚未保存，无法执行");
    return;
  }
  tagResetLoading.value = true;
  try {
    const res = await PostProblemTagReset(problemId);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    removedSavedTags.value = [];
    loadTagHistory();
    ShowTextTipsSuccess(globalProperties, "已交回 AI 管理，等下次审阅跑完生效");
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    tagResetLoading.value = false;
  }
};

// 变更历史的操作者展示：AI 与人工必须一眼可区分
const getTagChangeActor = (item: ProblemTagChange) => (item.source === "ai" ? "AI 审阅" : "人工");

const formatTagChangeTime = (value?: string) => (value ? new Date(value).toLocaleString() : "");

/** 读取 AI 服务可用性，决定是否展示 AI 相关入口 */
const loadAiEnabled = async () => {
  try {
    const res = await GetProblemJudge(problemKey.value);
    if (res.code === 0) {
      aiEnabled.value = res.data?.ai_enabled === true;
    }
  } catch {
    // 静默失败：AI 入口保持隐藏，不影响题目编辑主流程
  }
};

onMounted(async () => {
  if (Array.isArray(route.params.problemKey)) {
    problemKey.value = route.params.problemKey[0];
  } else {
    problemKey.value = route.params.problemKey;
  }

  if (problemKey.value) {
    problemLoading.value = true;
    GetProblemTagList(-1)
      .then(async (res) => {
        if (res.code === 0) {
          if (res.data.list) {
            res.data.list.forEach((tag: ProblemTag) => {
              problemTagOptions.value.push({
                label: tag.name,
                value: tag.id,
              });
            });
          }
          await loadProblem();
        } else {
          ShowErrorTips(globalProperties, res.code);
          console.error("problem tag get failed", res.code);
          await router.push({ name: "problem" });
        }
      })
      .catch(async (err) => {
        console.error(err);
        ShowErrorTips(globalProperties, "获取数据异常");
        await router.push({ name: "problem" });
      });
  } else {
    problemEditForm.value.timeLimit = 1000;
    problemEditForm.value.memoryLimit = 65536;

    loadDescriptionEditor("");
  }
});
</script>

<template>
  <t-loading :loading="problemLoading">
    <t-row>
      <t-col :span="isMobile ? 12 : 8">
        <div style="margin: 10px">
          <t-card class="sh-card">
            <t-form :model="problemEditForm">
              <t-form-item label="标题">
                <t-input v-model="problemEditForm.title" placeholder="问题标题"></t-input>
              </t-form-item>
              <t-form-item label="时间限制">
                <t-input-number v-model="problemEditForm.timeLimit" theme="normal" :min="0">
                  <template #suffix><span>ms</span></template>
                </t-input-number>
              </t-form-item>
              <t-form-item label="内存限制">
                <t-input-number v-model="problemEditForm.memoryLimit" theme="normal" :min="0">
                  <template #suffix><span>KB</span></template>
                </t-input-number>
              </t-form-item>
              <t-form-item label="来源">
                <t-input v-model="problemEditForm.source" placeholder="请输入题目来源"></t-input>
              </t-form-item>
              <t-form-item label="私有">
                <t-switch v-model="problemEditForm.private" />
              </t-form-item>
              <t-form-item label="空白字符" :help="spaceTypeDescription">
                <t-select v-model="problemEditForm.spaceType" :options="spaceTypeOptions" />
              </t-form-item>

              <t-form-item label="标签">
                <t-select-input
                  :value="problemTags"
                  :allow-input="true"
                  placeholder="请选择或输入"
                  :tag-input-props="{ excessTagsDisplayType: 'break-line' }"
                  :popup-props="{
                    overlayInnerClassName: ['narrow-scrollbar'],
                    overlayInnerStyle: {
                      maxHeight: '280px',
                      overflowY: 'auto',
                      overscrollBehavior: 'contain',
                      padding: '6px',
                    },
                  }"
                  clearable
                  multiple
                  @tag-change="onTagChange"
                >
                  <template #panel>
                    <t-checkbox-group
                      v-if="problemTagOptions.length"
                      :value="problemTagsCheckbox"
                      :options="problemTagOptions"
                      @change="onTagCheckedChange"
                    />
                    <div v-else>暂无数据</div>
                  </template>
                  <template #suffixIcon>
                    <ChevronDownIcon />
                  </template>
                </t-select-input>

                <!-- 来源分组：哪几个是 AI 补的，一眼可见，不用 hover 猜 -->
                <div v-if="problemTags.length" class="tag-source-line">
                  <span v-if="humanTags.length" class="tag-source-item">
                    <span class="tag-source-mark is-human">✎</span> 你加的：{{ humanTagNames }}
                  </span>
                  <span v-if="aiTags.length" class="tag-source-item">
                    <span class="tag-source-mark is-ai">●</span> AI 补充的：{{ aiTagNames }}
                  </span>
                </div>

                <!-- 删了就不会被 AI 加回来：这是用户最能感知的一条规则，必须明说 -->
                <div v-for="name in removedSavedTags" :key="name" class="tag-remove-notice">
                  <span>「{{ name }}」已移除，AI 审阅不会再自动加回。</span>
                  <t-link theme="primary" size="small" @click="handleRevokeRemoved(name)">撤销</t-link>
                </div>

                <div class="tag-action-line">
                  <t-button variant="text" theme="primary" size="small" @click="handleFindSimilar">
                    按标签查找相似题
                  </t-button>
                  <t-button
                    variant="text"
                    theme="primary"
                    size="small"
                    :loading="aiTagLoading"
                    @click="handleAiSuggestTags"
                  >
                    AI 生成标签
                  </t-button>
                </div>

                <div class="tag-ai-note">
                  <span>AI 审阅会自动补充主题标签，但不会改动你手动增删的部分。</span>
                  <t-popconfirm
                    content="将清空这道题的人工修改（被移除的标签重新允许 AI 添加），并让 AI 重新审阅。等下次审阅跑完才生效。"
                    @confirm="handleResetTagsToAi"
                  >
                    <t-link theme="primary" size="small" :loading="tagResetLoading">让 AI 重新决定</t-link>
                  </t-popconfirm>
                  <t-link theme="default" size="small" @click="showTagHistory = !showTagHistory">
                    {{ showTagHistory ? "收起改动记录" : "查看改动记录" }}
                  </t-link>
                </div>

                <!-- 改动记录：AI 与人工的动作都在这里，回答「AI 是不是偷偷改了我的东西」 -->
                <div v-if="showTagHistory" class="tag-history">
                  <t-loading :loading="tagHistoryLoading" size="small">
                    <div v-if="!tagHistory.length" class="tag-history-empty">暂无改动记录</div>
                    <div v-for="item in tagHistory" :key="item.id" class="tag-history-item">
                      <span class="tag-history-time">{{ formatTagChangeTime(item.insert_time) }}</span>
                      <span :class="['tag-history-actor', item.source === 'ai' ? 'is-ai' : 'is-human']">
                        {{ getTagChangeActor(item) }}
                      </span>
                      <span>{{ item.detail }}</span>
                    </div>
                  </t-loading>
                </div>
              </t-form-item>
            </t-form>
          </t-card>
        </div>
      </t-col>
      <t-col :span="isMobile ? 12 : 4">
        <div style="margin: 12px">
          <div class="dida-edit-container">
            <t-space v-if="problemId">
              <t-button theme="danger" :loading="isSaving" @click="handleClickSave">保存</t-button>
              <t-button theme="warning" @click="handleClickJudge">判题数据</t-button>
              <t-button v-if="aiEnabled" variant="outline" @click="handleClickAi">AI 生成测试数据</t-button>
              <t-button @click="handleClickView">查看</t-button>
            </t-space>
            <t-space v-else>
              <t-button theme="danger" :loading="isSaving" @click="handleClickCreate">创建</t-button>
            </t-space>
          </div>
          <t-descriptions v-if="problemId" layout="vertical" :bordered="true">
            <t-descriptions-item label="创建时间">{{ problemData?.insertTime }}</t-descriptions-item>
            <t-descriptions-item label="编辑时间">{{ problemData?.modifyTime }}</t-descriptions-item>
            <t-descriptions-item label="判题方式">{{ problemData?.judgeType }}</t-descriptions-item>
            <t-descriptions-item label="上传用户">{{ problemData?.inserterNickname }}</t-descriptions-item>
          </t-descriptions>
        </div>
      </t-col>
    </t-row>
    <div class="dida-description-editor">
      <p>题目描述</p>
      <t-loading :loading="disabledEdit || isSaving">
        <md-editor-v3
          v-model="problemEditForm.description"
          :toolbars="toolbars"
          preview-theme="cyanosis"
          @save="onEditSave"
          @on-upload-img="onUploadImg"
        >
          <template #defToolbars>
            <AIEnhancement v-model="problemEditForm.description" :ai-enabled="aiEnabled" />
          </template>
        </md-editor-v3>
      </t-loading>
    </div>
  </t-loading>
</template>

